#include <stdio.h>
#include <ApplicationServices/ApplicationServices.h>

void click_button(AXUIElementRef element, CFStringRef title_to_find) {
    CFArrayRef buttons;
    if (AXUIElementCopyAttributeValue(element, kAXButtonsAttribute, (CFTypeRef *)&buttons) == kAXErrorSuccess) {
        for (CFIndex i = 0; i < CFArrayGetCount(buttons); i++) {
            AXUIElementRef button = (AXUIElementRef)CFArrayGetValueAtIndex(buttons, i);
            CFStringRef title;
            if (AXUIElementCopyAttributeValue(button, kAXTitleAttribute, (CFTypeRef *)&title) == kAXErrorSuccess) {
                if (CFStringCompare(title, title_to_find, 0) == kCFCompareEqualTo) {
                    printf("Found button: %s\n", CFStringGetCStringPtr(title, kCFStringEncodingUTF8));
                    AXUIElementPerformAction(button, kAXPressAction);
                    printf("Clicked button!\n");
                }
                CFRelease(title);
            }
        }
        CFRelease(buttons);
    }
}

int main() {
    printf("Looking for iOS Simulator...\n");

    // Find the iOS Simulator process
    pid_t sim_pid = 0;
    ProcessSerialNumber psn = { 0, kNoProcess };

    while (GetNextProcess(&psn) == noErr) {
        pid_t pid;
        GetProcessPID(&psn, &pid);

        CFStringRef process_name = NULL;
        AXUIElementRef app = AXUIElementCreateApplication(pid);
        if (app) {
            AXUIElementCopyAttributeValue(app, kAXTitleAttribute, (CFTypeRef *)&process_name);
            if (process_name) {
                const char *name = CFStringGetCStringPtr(process_name, kCFStringEncodingUTF8);
                printf("Process: %s (pid: %d)\n", name ? name : "unknown", pid);

                if (name && (strstr(name, "Simulator") || strstr(name, "iOS"))) {
                    printf("Found Simulator!\n");
                    sim_pid = pid;
                    CFRelease(process_name);
                    CFRelease(app);
                    break;
                }
                CFRelease(process_name);
            }
            CFRelease(app);
        }
    }

    if (sim_pid > 0) {
        printf("Simulator PID: %d\n", sim_pid);

        AXUIElementRef app = AXUIElementCreateApplication(sim_pid);
        if (app) {
            // Get main window
            CFArrayRef windows;
            if (AXUIElementCopyAttributeValue(app, kAXWindowsAttribute, (CFTypeRef *)&windows) == kAXErrorSuccess) {
                if (CFArrayGetCount(windows) > 0) {
                    AXUIElementRef window = (AXUIElementRef)CFArrayGetValueAtIndex(windows, 0);
                    click_button(window, CFSTR("Open"));
                }
                CFRelease(windows);
            }
            CFRelease(app);
        }
    } else {
        printf("Simulator not found\n");
    }

    return 0;
}
