    if (AXUIElementCopyAttributeValue(element, kAXChildrenAttribute, (CFTypeRef *)&children) == kAXErrorSuccess) {
        if (children && CFArrayGetCount(children) < 20) {  // Limit to avoid spam
            for (CFIndex i = 0; i < CFArrayGetCount(children); i++) {
