    NSArray *apps = [workspace runningApplications];

    for (NSRunningApplication *app in apps) {
        NSString *name = app.localizedName ?: @"";
        if ([name rangeOfString:@"Simulator"].location != NSNotFound) {
            fprintf(stderr, "Found Simulator: %s\n", [name UTF8String]);
            pid_t pid = [app processIdentifier];

            AXUIElementRef appElement = AXUIElementCreateApplication(pid);

            // Get the window
            CFArrayRef windows = NULL;
            AXUIElementCopyAttributeValue(appElement, kAXWindowsAttribute, (CFTypeRef *)&windows);

            if (windows && CFArrayGetCount(windows) > 0) {
                AXUIElementRef window = (AXUIElementRef)CFArrayGetValueAtIndex(windows, 0);

                // Get the window position and size
                CFTypeRef position = NULL;
                CFTypeRef size = NULL;

                AXUIElementCopyAttributeValue(window, kAXPositionAttribute, &position);
                AXUIElementCopyAttributeValue(window, kAXSizeAttribute, &size);

                if (position && size) {
                    CGPoint pos;
                    CGSize sz;

                    AXValueGetValue(position, kAXValueTypeCGPoint, &pos);
                    AXValueGetValue(size, kAXValueTypeCGSize, &sz);

                    fprintf(stderr, "Window position: (%.0f, %.0f)\n", pos.x, pos.y);
                    fprintf(stderr, "Window size: (%.0f, %.0f)\n", sz.width, sz.height);

                    // The Weekend Plans row is approximately at y=710 in simulator coords
                    // Calculate the screen coordinates
                    double simulator_y = 710.0;
                    double screen_y = pos.y + (simulator_y * sz.height / 2340.0); // Assuming iPhone 12 is 1080x2340
                    double screen_x = pos.x + (sz.width / 2); // Center of the simulator

                    fprintf(stderr, "Calculated click position: (%.0f, %.0f)\n", screen_x, screen_y);

                    CFRelease(position);
                    CFRelease(size);
                }

                CFRelease(windows);
            }
            CFRelease(appElement);
            break;
        }
    }

    [pool release];
    return 0;
}
